class SplashPage extends StatefulWidget { const SplashPage({super.key}); @override State<SplashPage> createState() => _SplashPageState(); }
class _SplashPageState extends State<SplashPage> {
  @override void initState() { super.initState(); Future.delayed(const Duration(milliseconds: 900), () { if (mounted) Navigator.pushReplacement(context, MaterialPageRoute(builder: (_) => const HomePage())); }); }
  @override Widget build(BuildContext context) => Scaffold(backgroundColor: Colors.white, body: Center(child: SizedBox(width: 360, child: SvgPicture.asset('assets/rentflow_splash.svg'))));
}

class StoreDB extends ChangeNotifier {
  SharedPreferences? prefs;
  List<Map<String,dynamic>> shops = [];
  int activeShop = 0;
  bool get ready => prefs != null;
  Map<String,dynamic> get shop => shops.isEmpty ? <String,dynamic>{} : shops[activeShop];
  List<Map<String,dynamic>> records(String key) { final v=shop[key]; if(v is! List)return <Map<String,dynamic>>[]; return v.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList(); }
  Future<void> load() async { prefs=await SharedPreferences.getInstance(); try{final raw=jsonDecode(prefs!.getString('rentflow_data')??'[]'); if(raw is List)shops=raw.whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList();}catch(_){shops=[];} activeShop=prefs!.getInt('rentflow_active')??0; if(activeShop>=shops.length)activeShop=shops.isEmpty?0:shops.length-1; notifyListeners(); }
  Future<void> save() async { await prefs?.setString('rentflow_data',jsonEncode(shops)); await prefs?.setInt('rentflow_active',activeShop); notifyListeners(); }
  Future<void> addShop(Map<String,dynamic> data) async { shops.add({...data,'items':<Map<String,dynamic>>[],'customers':<Map<String,dynamic>>[],'issues':<Map<String,dynamic>>[],'returns':<Map<String,dynamic>>[]}); activeShop=shops.length-1; await save(); }
  Future<void> editShop(int i,Map<String,dynamic> data) async { shops[i].addAll(data); await save(); }
  Future<void> deleteShop(int i) async { shops.removeAt(i); activeShop=shops.isEmpty?0:(activeShop>=shops.length?shops.length-1:activeShop); await save(); }
  Future<void> addRecord(String key,Map<String,dynamic> data) async { final v=shop[key]; if(v is List)v.add(data); await save(); }
  Future<void> editRecord(String key,int i,Map<String,dynamic> data) async { final v=shop[key]; if(v is List&&i<v.length)v[i]=data; await save(); }
  Future<void> deleteRecord(String key,int i) async { final v=shop[key]; if(v is List&&i<v.length)v.removeAt(i); await save(); }
}
final store=StoreDB();
String newId()=>DateTime.now().microsecondsSinceEpoch.toString();
Future<void> openPage(BuildContext c,Widget w)=>Navigator.push(c,MaterialPageRoute(builder:(_)=>w));

