class PrimaryButton extends StatelessWidget{final String label;final IconData? icon;final VoidCallback? onPressed;const PrimaryButton({super.key,required this.label,required this.onPressed,this.icon});@override Widget build(BuildContext c)=>SizedBox(width:double.infinity,child:FilledButton.icon(onPressed:onPressed,icon:Icon(icon??Icons.check_rounded),label:Text(label),style:FilledButton.styleFrom(backgroundColor:emeraldDark,padding:const EdgeInsets.symmetric(vertical:15),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(12)))));}
class SectionTitle extends StatelessWidget{final String text;const SectionTitle(this.text,{super.key});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.only(bottom:10),child:Text(text,style:const TextStyle(fontSize:13,fontWeight:FontWeight.w900,color:emeraldDark,letterSpacing:1)));}
class EmptyState extends StatelessWidget{final String text;const EmptyState({super.key,required this.text});@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.all(28),child:Column(children:[const Icon(Icons.inbox_outlined,size:42,color:Colors.black26),const SizedBox(height:8),Text(text,style:const TextStyle(color:Colors.black54))]));}
class DataRowCard extends StatelessWidget{final String title,subtitle;final VoidCallback onEdit,onDelete;const DataRowCard({super.key,required this.title,required this.subtitle,required this.onEdit,required this.onDelete});@override Widget build(BuildContext c)=>Card(elevation:0,margin:const EdgeInsets.only(bottom:9),shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(14),side:const BorderSide(color:border)),child:ListTile(title:Text(title,style:const TextStyle(fontWeight:FontWeight.w800)),subtitle:Text(subtitle),trailing:PopupMenuButton<String>(onSelected:(v){if(v=='edit')onEdit();if(v=='delete')onDelete();},itemBuilder:(_)=>const[PopupMenuItem(value:'edit',child:Text('Edit')),PopupMenuItem(value:'delete',child:Text('Delete'))])));}
